<?php $root='admin/lucky-draw/'.$campaign['id']; ?>
<div class="lucky-detail">
<div class="record-heading-actions"><a class="btn" href="<?= url('admin/distribution?campaign='.$campaign['id']) ?>">Distribution map</a><a class="btn" href="<?= url('admin/lucky-draw') ?>">Back to promotions</a><a class="btn" href="<?= url('admin/lucky-draw/redeem') ?>">Give a prize</a><a class="btn" href="<?= url('lucky-draw') ?>" target="_blank" rel="noopener">Customer entry page</a></div>
<div class="panel lucky-summary"><div class="panel-heading"><div class="lucky-summary-meta"><span class="badge <?= $campaign['status']==='active'?'published':'draft' ?>"><?= e(ucfirst($campaign['status'])) ?></span><p><?= e($campaign['starts_on']) ?> through <?= e($campaign['ends_on']) ?>, Myanmar time</p></div>
<?php if (!$campaign['generated_at']): ?><form method="post" action="<?= url($root.'/generate') ?>"><?= csrf_field() ?><button class="btn btn-primary">Generate <?= number_format($campaign['total_codes']) ?> codes</button></form>
<?php else: ?><div class="record-heading-actions"><a class="btn" href="<?= url($root.'/print?autoprint=1') ?>">Print codes</a><a class="btn" href="<?= url($root.'/export') ?>">Export CSV</a><form method="post" action="<?= url($root.'/status') ?>"><?= csrf_field() ?><input type="hidden" name="status" value="<?= $campaign['status']==='active'?'paused':'active' ?>"><button class="btn btn-primary"><?= $campaign['status']==='active'?'Pause promotion':'Activate promotion' ?></button></form><?php if($campaign['status']!=='closed'): ?><form method="post" action="<?= url($root.'/status') ?>"><?= csrf_field() ?><input type="hidden" name="status" value="closed"><button class="btn">Close promotion</button></form><?php endif; ?></div><?php endif; ?></div>
<p><?= nl2br(e($campaign['instructions'])) ?></p>
