<div class="overview-kpis"><?php foreach(['generated'=>'Codes ready','played'=>'Played','winners'=>'Winners','collected'=>'Collected'] as $key=>$label): ?><div class="panel overview-metric"><span><?= e($label) ?></span><strong><?= number_format($stats[$key]) ?></strong></div><?php endforeach; ?></div>
<div class="panel"><h2>Prizes</h2><div class="table-wrap"><table><thead><tr><th>Prize</th><th>Available in batch</th><th>Won</th><th>Collected</th></tr></thead><tbody><?php foreach($prizes as $prize): ?><tr><td><?= e($prize['name']) ?></td><td><?= number_format($prize['quantity']) ?></td><td><?= number_format($prize['won']) ?></td><td><?= number_format($prize['collected']) ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="panel"><h2>Revealed winners</h2><?php if(!$winners): ?><p>No winning codes have been revealed yet.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>Code ending</th><th>Prize</th><th>Collection</th><th></th></tr></thead><tbody><?php foreach($winners as $winner): ?><tr><td>&hellip;<?= e(substr($winner['code'],-6)) ?></td><td><?= e($winner['prize_name']) ?></td><td><?= $winner['redeemed_at']?'Collected':'Awaiting collection' ?></td><td><a class="btn btn-sm" href="<?= url('admin/lucky-draw/redeem?code='.$winner['code']) ?>">Check prize</a></td></tr><?php endforeach; ?></tbody></table></div><div class="list-footer"><span>Page <?= $page ?> of <?= max(1,(int)ceil($stats['winners']/25)) ?></span><div class="record-heading-actions"><?php if($page>1): ?><a class="btn" href="<?= url($root.'?page='.($page-1)) ?>">Previous</a><?php endif; ?><?php if($page*25<$stats['winners']): ?><a class="btn" href="<?= url($root.'?page='.($page+1)) ?>">Next</a><?php endif; ?></div></div><?php endif; ?></div>
</div>
